<?php
namespace App\Console\Commands;
use Illuminate\Console\Command;use Illuminate\Support\Facades\Artisan;use Illuminate\Support\Facades\DB;use App\Models\AdminCommandRun;use App\Services\AdminConsole\AdminCommandRegistry;
class AdminConsoleProcess extends Command {protected $signature='admin-console:process {--max=3}';protected $description='Process safe queued admin console commands';public function handle():int{$n=0;while($n<(int)$this->option('max')&&($id=DB::transaction(function(){ $r=AdminCommandRun::where('status','pending')->orderBy('id')->lockForUpdate()->first();if(!$r)return null;$r->update(['status'=>'running','started_at'=>now()]);return $r->id;}))){$r=AdminCommandRun::find($id);$start=microtime(true);try{$params=array_merge($r->command_arguments?:[],$r->command_options?:[]);Artisan::call($r->command_name,$params);$out=$this->limit(Artisan::output());$r->update(['status'=>'success','exit_code'=>0,'stdout'=>$out,'finished_at'=>now(),'duration_ms'=>(int)((microtime(true)-$start)*1000)]);}catch(\Throwable $e){$r->update(['status'=>'failed','exit_code'=>1,'stderr'=>$this->limit($this->sanitize($e->getMessage())),'finished_at'=>now(),'duration_ms'=>(int)((microtime(true)-$start)*1000)]);} $n++;}return self::SUCCESS;}private function limit($s){$s=(string)$s;return strlen($s)>102400?substr($s,0,102400).'\n[OUTPUT TRUNCATED]':$s;}private function sanitize($s){return preg_replace('/(APP_KEY|DB_PASSWORD|GEMINI_API_KEY|CLIENT_SECRET|FTP_PASSWORD|authorization:\s*bearer)\s*[:=]?\s*[^\s]+/i','$1=[REDACTED]',$s);}}
